css:
.cl-page{--ink:#17202a;--blue:#2563eb;--blue-d:#1e40af;--tint:#eef3ff;--mute:#5b6675;--line:#e2e8f0;--grey:#c3ccd8;max-width:1040px;margin:0 auto;padding:56px 28px 96px;background:#fff;color:var(--ink);font-family:var(--page-sans),'Pretendard','Apple SD Gothic Neo','Noto Sans KR',sans-serif;font-size:16.5px;line-height:1.75;word-break:keep-all;overflow-wrap:break-word;box-sizing:border-box}
.cl-page *,.cl-page *::before,.cl-page *::after{box-sizing:border-box}
.cl-page h1,.cl-page h2,.cl-page h3,.cl-page p,.cl-page ul,.cl-page ol,.cl-page dl,.cl-page dd,.cl-page figure{margin:0;padding:0}
.cl-page ul,.cl-page ol{list-style:none}

.cl-hero{display:grid;grid-template-columns:minmax(0,1.05fr) minmax(0,1fr);gap:56px;align-items:end;padding-bottom:48px}
.cl-role{color:var(--blue-d);font-weight:700;font-size:18px;line-height:1.4}
.cl-name{font-size:clamp(46px,8vw,76px);font-weight:800;letter-spacing:-.03em;line-height:1.08;margin-top:6px}
.cl-lead{margin-top:22px;font-size:clamp(19px,2.2vw,22px);line-height:1.6;font-weight:500;max-width:30em}

.cl-proof{border-left:4px solid var(--blue);padding:4px 0 4px 28px}
.cl-proof-title{font-weight:700;font-size:15px;color:var(--mute);line-height:1.4}
.cl-pair{margin-top:18px;display:grid;gap:12px}
.cl-proof figcaption{margin-top:18px;font-size:14px;color:var(--mute);line-height:1.5}
.cl-pair .cl-row{grid-template-columns:36px minmax(0,1fr) auto}
.cl-when{font-size:14px;font-weight:600;color:var(--mute)}
.cl-when-new{color:var(--blue-d)}

.cl-row{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:12px;align-items:center}
.cl-track{display:block;height:30px;background:transparent;position:relative}
.cl-bar{display:block;height:100%;width:var(--w);transform-origin:left center;animation:cl-grow .9s cubic-bezier(.2,.7,.2,1) both}
.cl-bar-old{background:var(--grey)}
.cl-bar-new{background:var(--blue);animation-delay:.35s}
.cl-val{font-family:var(--page-display),var(--page-sans),sans-serif;font-variant-numeric:tabular-nums;font-weight:600;font-size:18px;min-width:3.4em;line-height:1.2;color:var(--mute)}
.cl-val-new{color:var(--blue-d);font-weight:800}
@keyframes cl-grow{from{transform:scaleX(0)}to{transform:scaleX(1)}}

.cl-facts{display:grid;grid-template-columns:repeat(3,1fr);border-top:1px solid var(--ink);border-bottom:1px solid var(--line)}
.cl-facts li{padding:20px 24px 20px 0;display:flex;flex-direction:column;gap:2px}
.cl-facts li+li{padding-left:24px;border-left:1px solid var(--line)}
.cl-fact-num{font-family:var(--page-display),var(--page-sans),sans-serif;font-weight:700;font-size:clamp(20px,2.6vw,26px);line-height:1.3;letter-spacing:-.01em;font-variant-numeric:tabular-nums}
.cl-fact-label{font-size:14px;color:var(--mute);line-height:1.5}

.cl-sec{padding-top:80px}
.cl-sec h2{font-size:clamp(24px,3.4vw,32px);font-weight:700;line-height:1.35;letter-spacing:-.02em;max-width:22em}
.cl-period{margin-top:8px;color:var(--mute);font-size:14.5px;font-variant-numeric:tabular-nums;line-height:1.5}
.cl-body{margin-top:24px;max-width:46em}
.cl-body>p{max-width:40em}

.cl-defs{margin-top:28px;border-top:1px solid var(--line)}
.cl-defs>div,.cl-ledger>div{display:grid;grid-template-columns:150px minmax(0,1fr);gap:20px;padding:13px 0;border-bottom:1px solid var(--line)}
.cl-defs dt,.cl-ledger dt{font-weight:700;color:var(--blue-d)}
.cl-ledger{margin-top:32px;border-top:1px solid var(--ink)}
.cl-ledger>div{padding:16px 0}

.cl-lead-sec{margin-top:80px;padding:56px 40px 48px;background:var(--tint);border-top:3px solid var(--blue)}
.cl-case{margin-top:36px;display:grid;grid-template-columns:minmax(0,1.1fr) minmax(0,1fr);gap:56px;align-items:start}
.cl-story{display:grid;gap:22px}
.cl-beat{display:grid;grid-template-columns:56px minmax(0,1fr);gap:16px}
.cl-beat h3{font-size:16px;font-weight:700;color:var(--mute);line-height:1.75}
.cl-beat p{max-width:34em}
.cl-beat-result h3{color:var(--blue-d)}
.cl-beat-result p{font-weight:600}
.cl-charts{display:grid;gap:30px}
.cl-chart-title{font-weight:700;font-size:15px;margin-bottom:8px;line-height:1.4}
.cl-chart .cl-row+.cl-row{margin-top:6px}
.cl-chart .cl-track{height:26px}

.cl-steps{margin-top:40px;counter-reset:step;display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:0;border-top:1px solid var(--ink)}
.cl-steps li{counter-increment:step;padding:16px 20px 4px 0;font-size:15px;line-height:1.65;color:var(--ink)}
.cl-steps li+li{padding-left:20px;border-left:1px solid var(--line)}
.cl-steps li::before{content:counter(step);display:block;font-family:var(--page-display),sans-serif;font-weight:700;color:var(--blue);font-size:15px;line-height:1.4}
.cl-steps b{display:block;font-size:15px;line-height:1.5;margin-bottom:2px}
.cl-lead-sec .cl-steps{border-top-color:var(--blue)}
.cl-lead-sec .cl-steps li+li{border-left-color:#cfdbf7}
.cl-tools{margin-top:24px;font-size:14.5px;color:var(--blue-d);font-weight:600;line-height:1.5}

.cl-case-small{grid-template-columns:minmax(0,1.1fr) minmax(0,1fr)}

.cl-evidence{margin-top:0}
.cl-ev-grid{margin-top:28px;display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:56px;align-items:start}
.cl-ev-grid h3{font-size:16px;font-weight:700;color:var(--blue-d);padding-bottom:10px;border-bottom:1px solid var(--ink);line-height:1.5}
.cl-ev li{padding:14px 0;border-bottom:1px solid var(--line);display:grid;gap:2px;font-size:15px;line-height:1.65}
.cl-ev li b{font-weight:700;font-size:16px}
.cl-ev li span{color:var(--mute)}
.cl-ev .cl-ev-date{font-size:13.5px;font-variant-numeric:tabular-nums;color:var(--blue-d)}

.cl-page a:focus-visible,.cl-page summary:focus-visible{outline:3px solid var(--blue);outline-offset:3px}

@media (max-width:820px){
.cl-page{padding:36px 20px 72px;font-size:16px}
.cl-hero{grid-template-columns:minmax(0,1fr);gap:36px;padding-bottom:36px}
.cl-proof{padding-left:20px}
.cl-facts{grid-template-columns:minmax(0,1fr)}
.cl-facts li,.cl-facts li+li{padding:14px 0;border-left:0}
.cl-facts li+li{border-top:1px solid var(--line)}
.cl-sec{padding-top:60px}
.cl-lead-sec{margin-top:60px;padding:36px 20px 32px}
.cl-case,.cl-case-small{grid-template-columns:minmax(0,1fr);gap:32px}
.cl-defs>div,.cl-ledger>div{grid-template-columns:minmax(0,1fr);gap:2px}
.cl-beat{grid-template-columns:48px minmax(0,1fr);gap:12px}
.cl-steps{grid-template-columns:minmax(0,1fr)}
.cl-steps li,.cl-steps li+li{padding:14px 0;border-left:0}
.cl-steps li+li{border-top:1px solid var(--line)}
.cl-ev-grid{grid-template-columns:minmax(0,1fr);gap:40px}
}

@media (prefers-reduced-motion:reduce){
.cl-bar{animation:none}
}
